async function resetLearning(){
 if(resetBusy||!adminLoggedIn||uid!==ADMIN_UID){msg('Nur der Schiedsrichter darf Lernstände löschen.',true);return;}
 const target=document.querySelector('#reset-target')?.value;
 const subject=document.querySelector('#reset-subject')?.value;
 const moduleId=document.querySelector('#reset-box')?.value;
 if(target!=='all'&&!SOLO_NAMES.includes(target)){msg('Bitte ein Kind auswählen.',true);return;}
 if(!['english','math'].includes(subject)){msg('Bitte ein Fach auswählen.',true);return;}
 const selected=moduleId==='all'?null:(LEARNING_RESET_MODULES[subject]||[]).find(x=>x[0]===moduleId);
 if(moduleId!=='all'&&!selected){msg('Bitte ein Lernkästchen auswählen.',true);return;}
 const label=target==='all'?'ALLE VIER KINDER':target;
 const subjectLabel=subject==='math'?'Mathe':'Englisch';
 const moduleLabel=selected?selected[1]:`alle ${subjectLabel}-Lernkästchen`;
 if(!window.confirm(`ACHTUNG: ${moduleLabel} für ${label} zurücksetzen? Die übrigen Lernkästchen bleiben erhalten.`))return;
 if(!window.confirm(`Endgültig ${moduleLabel} für ${label} löschen?`))return;
 resetBusy=true;
 try{
  const targets=target==='all'?SOLO_NAMES:[target];
  const progressPath=subject==='math'?'mathProgress':'soloProgress';
  const resetPath=subject==='math'?'learningResetsMath':'learningResetsEnglish';
  const stamp=Date.now();
  for(const name of targets){await set(ref(db,selected?resetPath+'/'+name+'__'+moduleId:resetPath+'/'+name),stamp);if(subject==='math'&&selected&&selected[0].startsWith('fraction_'))await set(ref(db,'learningResets/'+name+'__math_'+moduleId),stamp);}
  const snap=await get(ref(db,progressPath));
  const paths={};
  for(const [device,perDevice] of Object.entries(snap.val()||{})){
   for(const name of targets){
    const records=perDevice?.[name];if(!records)continue;
    const keys=selected?selected[2]:Object.keys(records);
    for(const key of keys)if(Object.prototype.hasOwnProperty.call(records,key))paths[`${device}/${name}/${key}`]=null;
   }
  }
  if(Object.keys(paths).length)await update(ref(db,progressPath),paths);
  msg(`${moduleLabel} für ${label} zurückgesetzt. Die übrigen Lernkästchen bleiben erhalten.`);
 }catch(e){msg('Rücksetzen nicht vollständig abgeschlossen: '+e.message,true);}
 finally{resetBusy=false;}
}
