async function saveGrammarProgress(player,station,index,correct,runId,total){if(!player?.uid||!player?.name)return;const progressRef=ref(db,`soloProgress/${player.uid}/${player.name}/grammarStation${station+1}`);await runTransaction(progressRef,current=>{const next=current?.runId===runId?{...current}:{runId,done:0,score:0,correct:0,mistakes:{}};const mistakes={...(next.mistakes||{})};if(!correct)mistakes[index]=(Number(mistakes[index])||0)+1;next.done=Math.min(total,(Number(next.done)||0)+1);next.score=(Number(next.score)||0)+(correct?10:0);next.correct=(Number(next.correct)||0)+(correct?1:0);next.total=total;next.station=station+1;next.mistakes=mistakes;next.finished=next.done>=total;next.updatedAt=Date.now();next.timestamp=next.updatedAt;return next;});}
async function gbHost(action){if(!adminLoggedIn||uid!==ADMIN_UID||gbRoom?.meta?.hostUid!==uid||gbBusy)return;gbBusy=true;try{const m=gbRoom.meta,qs=gbQuestions(Number(m.station));if(action==='gbStart'){if(!gbPlayers().length){msg('Mindestens ein Spieler muss beitreten.',true);return;}const runId=`${Date.now()}-${Math.random().toString(36).slice(2,8)}`;await update(ref(db,`grammarRooms/${gbCode}/meta`),{stage:'question',index:0,deadline:Date.now()+GB_TIME,runId});}
else if(action==='gbNext'){const n=Number(m.index)+1;await update(ref(db,`grammarRooms/${gbCode}/meta`),n>=qs.length?{stage:'finished',deadline:0}:{stage:'question',index:n,deadline:Date.now()+GB_TIME});}
else if(action==='gbRestart'){await remove(ref(db,`grammarRooms/${gbCode}/submissions`));await remove(ref(db,`grammarRooms/${gbCode}/reviews`));for(const p of gbPlayers())await set(ref(db,`grammarRooms/${gbCode}/slots/${p.id}/score`),0);await update(ref(db,`grammarRooms/${gbCode}/meta`),{stage:'lobby',index:0,deadline:0});}
else {const yes=action.startsWith('gbYes_'),playerUid=action.slice(yes?6:5),ans=gbRoom.submissions?.[m.index]?.[playerUid];if(!ans||gbRoom.reviews?.[m.index]?.[playerUid])return;await set(ref(db,`grammarRooms/${gbCode}/reviews/${m.index}/${playerUid}`),{correct:yes,at:Date.now()});const p=gbPlayers().find(x=>x.uid===playerUid);if(p){if(yes)await runTransaction(ref(db,`grammarRooms/${gbCode}/slots/${p.id}/score`),x=>(Number(x)||0)+10);await saveGrammarProgress(p,Number(m.station)||0,Number(m.index)||0,yes,m.runId||`${gbCode}-${m.createdAt||0}`,qs.length);}}}catch(e){msg('Grammatik-Aktion fehlgeschlagen: '+e.message,true);}finally{gbBusy=false;}}

